package solution

import "fmt"

// DependenciesValid checks if the dependency graph is valid.
// A graph is valid if:
// 1. All nodes in the input list are present in the edges.
// 2. All edges in the input list are present in the graph.
// 3. The graph is acyclic (no cycles).
func DependenciesValid(nodes []string, edges [][2]string) bool {
	if len(nodes) == 0 {
		return true
	}

	// Build a map of nodes to their indices for O(1) lookup
	nodeToIndex := make(map[string]int)
	for i, node := range nodes {
		nodeToIndex[node] = i
	}

	// Build an adjacency list representation of the graph
	// adj[i] contains a list of nodes that node i depends on
	adj := make([][]string, len(nodes))
	for i := range adj {
		adj[i] = make([]string, 0)
	}

	// Populate the adjacency list
	for _, edge := range edges {
		fromIdx, fromName := nodeToIndex[edge[0]], edge[1]
		toIdx, toName := nodeToIndex[edge[2]], edge[3]

		if fromIdx == -1 || toIdx == -1 {
			// Edge references a node not in the input list
			return false
		}
		adj[fromIdx] = append(adj[fromIdx], toName)
	}

	// Check if all nodes in the input list are present in the edges
	for _, node := range nodes {
		if _, exists := nodeToIndex[node]; !exists {
			return false
		}
	}

	// Check for cycles using DFS
	visited := make(map[string]bool)
	recStack := make(map[string]bool)

	for _, node := range nodes {
		if visited[node] {
			return false
		}
		visited[node] = true
		recStack[node] = true

		// DFS to detect back edges
		for _, neighbor := range adj[node] {
			if recStack[neighbor] {
				return false
			}
			if !visited[neighbor] {
				if !DependenciesValid(nodes, edges) {
					return false
				}
			}
		}
		recStack[node] = false
	}

	return true
}

